class RightClick{static init(){this.enabled=!0,document.oncontextmenu=function(){return this.enabled},document.onkeydown=function(t){t.ctrlKey&&"M"==t.key.toUpperCase()&&this.toggle()},document.onmousedown=function(t){return this.enabled||1==t.button},document.onmouseup=function(t){return this.enabled||1==t.button}}static toggle(){this.enabled=!this.enabled}}RightClick.init();